input type="checkbox" name="watershed_enabled" value="1" <?=$s['watershed_enabled']?'checked':''?>>Watershed：接触した種子を分離</label><label class="toggle"><input type="checkbox" name="clahe_enabled" value="1" <?=$s['clahe_enabled']?'checked':''?>>CLAHE：照明ムラを補正</label><label>対象色<select name="foreground"><option value="dark" <?=$s['foreground']==='dark'?'selected':''?>>背景より暗い</option><option value="light" <?=$s['foreground']==='light'?'selected':''?>>背景より明るい</option></select></label></section><?php foreach($items as$it):?><section class="card parameter-card"><div class="parameter-head"><div><h2><?=h($it[1])?></h2><p><?=h($it[2])?></p><small>標準値：<?=h($it[3])?></small></div><div class="parameter-input"><input name="<?=h($it[0])?>" type="number" value="<?=h($s[$it[0]])?>" step="any"></div></div></section><?php endforeach;?><section class="card sticky-save"><button class="primary">形態解析パラメータを保存</button><?php if($message):?><p class="success"><?=h($message)?></p><?php endif;?><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?></section></form></main></body></html>
